const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const lines = theme.colors.border.weak;
const frame = context.panel.data.series[0];
const col = (name) => {
  const field = frame && frame.fields.find((f) => f.name === name);
  return field ? Array.from(field.values) : [];
};
const COLORS = {"Cargo": "#F29E2E", "Tanker": "#E5484D", "Passenger": "#00A6CA", "Fishing": "#90EB9D", "Leisure": "#C77DFF", "Service": "#FFD166", "Other": "#8B8D98"};
// Ships present, hour by hour, stacked by kind: the hours ships spent in the
// network's waters in each hour, which is how many were there on average.
const times = col('time');
const kinds = col('kind');
const ships = col('ships');
const order = Object.keys(COLORS).filter((k) => kinds.includes(k));
const buckets = [...new Set(times)].sort((a, b) => a - b);
const series = order.map((k) => {
  const at = new Map();
  kinds.forEach((kind, i) => kind === k && at.set(times[i], ships[i]));
  return { name: k, type: 'bar', stack: 'all', barMaxWidth: 10, itemStyle: { color: COLORS[k] },
           data: buckets.map((t) => [t, at.get(t) ?? 0]) };
});
return {
  animation: false,
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 10, itemHeight: 10 },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  tooltip: { trigger: 'axis' },
  xAxis: { type: 'time', axisLabel: { color: muted }, axisLine: { lineStyle: { color: lines } } },
  yAxis: { type: 'value', min: 0, axisLabel: { color: muted }, splitLine: { lineStyle: { color: lines } } },
  series,
};

const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const lines = theme.colors.border.weak;
const frame = context.panel.data.series[0];
const col = (name) => {
  const field = frame && frame.fields.find((f) => f.name === name);
  return field ? Array.from(field.values) : [];
};
const COLORS = {"Cargo": "#F29E2E", "Tanker": "#E5484D", "Passenger": "#00A6CA", "Fishing": "#90EB9D", "Leisure": "#C77DFF", "Service": "#FFD166", "Other": "#8B8D98"};
// Ships by kind, from the type each ship declares. A click on a bar filters the
// whole dashboard by it ($kind); a click on the picked bar clears the filter.
const VAR = 'kind';
const values = col('value').reverse();
const labels = col('label').reverse();
const counts = col('ships').reverse();
const picked = context.grafana.replaceVariables('${' + VAR + '}');
const location = context.grafana.locationService;

const chart = context.panel.chart;
chart.off('click');
chart.on('click', (event) => {
  const value = values[event.dataIndex];
  const current = context.grafana.replaceVariables('${' + VAR + '}');
  location.partial({ ['var-' + VAR]: value === current ? '' : value }, true);
});

return {
  animation: false,
  grid: { left: 8, right: 56, top: 8, bottom: 8, containLabel: true },
  tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' },
             formatter: (items) => `<b>${labels[items[0].dataIndex]}</b><br/>${counts[items[0].dataIndex].toLocaleString()} ships<br/><i>click to ${values[items[0].dataIndex] === picked ? 'clear the filter' : 'filter by it'}</i>` },
  xAxis: { type: 'value', axisLabel: { show: false }, splitLine: { show: false } },
  yAxis: { type: 'category', data: labels, axisLabel: { color: text }, axisLine: { lineStyle: { color: lines } } },
  series: [{
    name: 'Ships', type: 'bar', barMaxWidth: 16, cursor: 'pointer',
    data: counts.map((v, i) => ({
      value: v,
      itemStyle: { color: COLORS[values[i]] || '#8B8D98', opacity: !picked || values[i] === picked ? 1 : 0.3 },
    })),
    label: { show: true, position: 'right', color: muted, formatter: (p) => p.value.toLocaleString() },
  }],
};

const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const lines = theme.colors.border.weak;
const frame = context.panel.data.series[0];
const col = (name) => {
  const field = frame && frame.fields.find((f) => f.name === name);
  return field ? Array.from(field.values) : [];
};
const COLORS = {"Cargo": "#F29E2E", "Tanker": "#E5484D", "Passenger": "#00A6CA", "Fishing": "#90EB9D", "Leisure": "#C77DFF", "Service": "#FFD166", "Other": "#8B8D98"};
// The speed over ground of each ship followed, as it reported it. Flat at zero
// is a stop; a gap is a stretch the network did not hear it.
const times = col('time');
const names = col('name');
const knots = col('knots');
const PALETTE = ['#4cc9f0', '#f72585', '#ffb703', '#80ed99', '#b388eb', '#ff7f51'];
const byName = new Map();
names.forEach((n, i) => {
  if (!byName.has(n)) byName.set(n, []);
  byName.get(n).push([times[i], knots[i]]);
});
// Break a line where the ship went unheard for over ten minutes.
const withGaps = (points) => points.flatMap((p, i) => (i && p[0] - points[i - 1][0] > 600000 ? [[p[0] - 1, null], p] : [p]));
const series = [...byName.keys()].sort().map((n, i) => ({
  name: n, type: 'line', showSymbol: false, connectNulls: false, lineStyle: { width: 1.5 },
  itemStyle: { color: PALETTE[i % PALETTE.length] }, data: withGaps(byName.get(n)),
}));
if (!series.length) {
  return { title: { text: 'Follow a ship from the trips or encounters tables', left: 'center', top: 'middle',
                    textStyle: { color: muted, fontSize: 13, fontWeight: 'normal' } } };
}
return {
  animation: false,
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 10, itemHeight: 10 },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  tooltip: { trigger: 'axis', valueFormatter: (v) => (v == null ? '–' : `${v} kn`) },
  xAxis: { type: 'time', axisLabel: { color: muted }, axisLine: { lineStyle: { color: lines } } },
  yAxis: { type: 'value', min: 0, name: 'knots', nameTextStyle: { color: muted }, axisLabel: { color: muted },
           splitLine: { lineStyle: { color: lines } } },
  series,
};
